//--- el helicoptero no llego (se perdio o dio vueltas): se cancela y se devuelve el dinero
{deleteVehicle _x} forEach (crew _veh);
deleteVehicle _veh;
{deleteVehicle _x} forEach (units _cg);

steps.text:
//--- el helicoptero no llego (se perdio o dio vueltas): se cancela y se devuelve el dinero
//--- VIOC heli_join: si va un jugador dentro, primero sale; el aparato no se borra con un jugador dentro
[_veh, _cg] spawn {params ["_veh", "_cg"]; [_veh] call VIOC_fnc_pjSafeDelete; {deleteVehicle _x} forEach (units _cg)};

//--- VIOC heli_join: el helicoptero aterrizo (o no pudo y se vuelve): los jugadores que van dentro bajan ya (o saltan si
//--- aun vuela alto; su paracaidas se abre solo). Espera hasta 10 s a que salgan antes de que el helicoptero despegue.
VIOC_fnc_pjOut = {
	params ["_veh"];
	if (isNull _veh) exitWith {};
	private _pl = (crew _veh) select {isPlayer _x};
	if (count _pl == 0) exitWith {};
	{[_veh] remoteExecCall ["VIOC_PJ_fnc_out", _x]} forEach _pl;
	private _t = time + 10;
	waitUntil {sleep 0.5; isNull _veh || {({isPlayer _x} count (crew _veh)) == 0} || {time > _t}};
};

params ["_veh", "_lo", "_chute", "_label", ["_heli", false]];	//--- VIOC heli_join: + en helicoptero (con tu equipo)
[_veh, _lo, _chute, _label, _heli] spawn {
	params ["_veh", "_lo", "_chute", "_label", "_heli"];

//--- VIOC heli_join: ir en el helicoptero de tu operacion pedida, CON TU EQUIPO (no se cambia ni se guarda). Al aterrizar
//--- el servidor te baja con el equipo (VIOC_PJ_fnc_out). Si lo alcanzan en el aire decides tu si saltas (rueda:
//--- Saltar/Eject); en la caida el paracaidas se abre solo a VIOC_PJ_OPEN_AGL m (sin dano de caida, como en los saltos).
VIOC_PJ_fnc_rideHeli = {
	params ["_veh", "_chute", "_label"];
	if (vehicle player != player) then {moveOut player; sleep 0.3};
	player moveInCargo _veh;
	sleep 0.5;
	if (vehicle player != _veh && {alive _veh}) then {player moveInCargo _veh; sleep 0.5};
	if (vehicle player != _veh) exitWith {
		VIOC_PJ_RIDE = nil;
		["No pudiste subir al helicoptero (sin sitio o ya no esta)."] call VIOC_PJ_fnc_msg;
	};
	hint parseText format ["<t size='1.1' color='#ffb27f'>Insercion en helicoptero</t><br/><br/><t align='left'>Vas en el helicoptero de %1 con tu equipo. Cuando aterrice bajas con ellos.<br/><br/>Si lo alcanzan en el aire, decides tu si saltas (rueda: Saltar/Eject); el paracaidas se abre solo a %2 m.</t>", _label, VIOC_PJ_OPEN_AGL];
	private _warned = false;
	waitUntil {
		sleep 0.25;
		if (!_warned && {vehicle player == _veh} && {alive _veh} && {(damage _veh > 0.3) || {!canMove _veh} || {!alive (driver _veh)}} && {(call VIOC_PJ_fnc_agl) > 60}) then {
			_warned = true;
			hint parseText "<t size='1.3' color='#F56363'>El helicoptero fue alcanzado! Salta ahora</t><br/>(rueda: Saltar/Eject)";
		};
		(vehicle player != _veh) || {!alive player}
	};
	if (alive player && {alive _veh}) then {[[], _chute param [1, "Steerable_Parachute_F"], _veh] call VIOC_PJ_fnc_fall};
	VIOC_PJ_RIDE = nil;
};

//--- VIOC heli_join: orden del servidor (VIOC_fnc_pjOut): bajar ya del helicoptero, o saltar si aun vuela alto.
VIOC_PJ_fnc_out = {
	params ["_veh"];
	if (isNull _veh || {vehicle player != _veh}) exitWith {};
	private _h = (getPosATL _veh) select 2;
	if (_h > 15) exitWith {[_veh] call VIOC_PJ_fnc_doJump};
	if (_h > 3) then {[player, _veh, 20] call VIOC_PJ_fnc_guard};
	moveOut player;
};
